import {
	View,
	TextInput,
	Pressable,
	Modal,
	FlatList,
	Text,
	TouchableOpacity,
	Platform
} from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import {
	HeaderBar,
	Button,
	AnimatedFlatList,
	SearchBarContainer,
	SearchBarOverlay
} from '@/components'
import { router, useLocalSearchParams } from 'expo-router'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { useRef, useState } from 'react'
import { EmptyStateContainer } from '@/screens/home/components/EmptyStateContainer'
import Animated, { LinearTransition, Easing } from 'react-native-reanimated'
import { Image } from 'expo-image'
import { LinearGradient } from 'expo-linear-gradient'
import {
	GestureTrigger,
	GestureViewer
} from 'react-native-gesture-image-viewer'
import { Download, X } from 'lucide-react-native'
import { MenuAction, MenuView } from '@react-native-menu/menu'
import {
	DeleteAssetBottomSheet,
	DeleteAssetBottomSheetRef
} from '@/screens/project/components/DeleteAssetBottomSheet'
import { useUploadAsset } from '@/utils/hooks/useUploadAsset'
import { useSaveToGallery } from '@/utils/hooks/useSaveToGallery'
import {
	useGetAssetsQuery,
	useDeleteAssetMutation,
	OrderByDirection
} from '@/generated/graphql'
import { toast } from '@/utils/toast'

const COLUMN_COUNT = 3
const ITEM_SPACING = 4
const SEARCH_PLACEHOLDER = 'Search in assets'
const DEFAULT_IMAGE_NAME = 'image'

const triggerAnimationConfig = {
	duration: 300,
	easing: Easing.bezier(0.25, 0.1, 0.25, 1.0)
}

const menuActions: MenuAction[] = [
	{
		id: 'download',
		title: 'Download',
		image: Platform.select({
			ios: 'arrow.down.to.line',
			android: 'ic_menu_save'
		})
	},
	{
		id: 'delete',
		title: 'Delete Asset',
		attributes: {
			destructive: true
		},
		image: Platform.select({
			ios: 'trash',
			android: 'ic_menu_delete'
		}),
		imageColor: 'red'
	}
]

export const ProjectAssetsScreen = () => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()
	const { uploadAsset, isUploading: isUploadingAsset } = useUploadAsset()
	const LIST_BOTTOM_INSET = insets.bottom + 100
	const { download } = useSaveToGallery()

	const { projectGroupId, projectId } = useLocalSearchParams<{
		projectGroupId?: string
		projectId?: string
	}>()

	const {
		data: assetsData,
		loading: assetsLoading,
		refetch
	} = useGetAssetsQuery({
		variables: {
			first: 100,
			input: {
				projectGroupId,
				orderBy: { createdAt: OrderByDirection.DESC }
			}
		},
		skip: !projectGroupId
	})

	const [deleteAsset] = useDeleteAssetMutation()

	const [searchValue, setSearchValue] = useState('')
	const [isSearchBarOpen, setIsSearchBarOpen] = useState(false)
	const searchInputRef = useRef<TextInput>(null)
	const [isGalleryOpen, setIsGalleryOpen] = useState(false)
	const [selectedImageIndex, setSelectedImageIndex] = useState(0)
	const [showUI, setShowUI] = useState(true)
	const deleteBottomSheetRef = useRef<DeleteAssetBottomSheetRef>(null)

	const onClose = () => {
		router.back()
	}

	const handleUploadImage = async () => {
		const hasRequiredIds = projectGroupId && projectId
		if (!hasRequiredIds) {
			return
		}

		let result
		try {
			result = await uploadAsset({ projectGroupId })
		} catch {
			return
		}

		if (result.success) {
			refetch()
		}
	}

	const openGallery = (index: number) => {
		setSelectedImageIndex(index)
		setShowUI(true)
		setIsGalleryOpen(true)
	}

	const handleDismiss = () => {
		setIsGalleryOpen(false)
	}

	const handleDismissStart = () => {
		setShowUI(false)
	}

	const handleIndexChange = (index: number) => {
		setSelectedImageIndex(index)
	}

	const assets = assetsData?.assets?.edges?.map((edge) => edge.node) || []

	const filteredAssets = (() => {
		if (!searchValue) {
			return assets
		}
		return assets.filter((asset) =>
			asset.userDefinedName?.toLowerCase().includes(searchValue.toLowerCase())
		)
	})()

	const handleDownload = async () => {
		const asset = filteredAssets[selectedImageIndex]
		if (asset?.url) {
			const fileName = asset.userDefinedName || DEFAULT_IMAGE_NAME
			await download({ url: asset.url, fileName })
		}
	}

	const handleDeleteAsset = async (id: string) => {
		try {
			await deleteAsset({
				variables: {
					input: { id }
				}
			})
			toast.show({
				message: 'Asset deleted successfully',
				variant: 'success'
			})
		} catch {
			toast.show({
				message: 'Failed to delete asset',
				variant: 'error'
			})
			return
		}

		const bottomSheetRef = deleteBottomSheetRef.current
		if (bottomSheetRef) {
			bottomSheetRef.close()
		}
		refetch()
	}

	const handlePressMenuAction = (
		actionId: string,
		assetId: string,
		assetTitle: string
	) => {
		if (actionId === 'download') {
			handleDownload()
		} else if (actionId === 'delete') {
			deleteBottomSheetRef.current?.open(assetId, assetTitle)
		}
	}

	const renderImage = (imageUrl: string) => {
		return (
			<Image
				source={{ uri: imageUrl }}
				style={styles.fullSize}
				pointerEvents="none"
				contentFit="contain"
			/>
		)
	}

	const renderListEmptyComponent = () => (
		<View style={styles.emptyStateWrapper}>
			<EmptyStateContainer
				isShining={false}
				isEmpty={!assetsLoading}
				isRefreshing={assetsLoading}
				onRefresh={refetch}
				text={searchValue ? 'No assets match your search' : 'No assets found'}
			/>
		</View>
	)

	const renderAssetItem = ({ item, index }: { item: any; index: number }) => (
		<Animated.View
			style={styles.thumbnailWrapper}
			key={item.id}
			layout={LinearTransition}
		>
			<GestureTrigger id="assets" onPress={() => openGallery(index)}>
				<Pressable
					style={styles.thumbnail}
					onPress={null}
					onLongPress={null}
					delayLongPress={9999}
				>
					<MenuView
						actions={menuActions}
						onPressAction={({ nativeEvent }) =>
							handlePressMenuAction(
								nativeEvent.event,
								item.id,
								item.userDefinedName || DEFAULT_IMAGE_NAME
							)
						}
						shouldOpenOnLongPress
					>
						<Image
							source={{ uri: item.url }}
							contentFit="cover"
							style={styles.thumbnailImage}
						/>
					</MenuView>
				</Pressable>
			</GestureTrigger>
		</Animated.View>
	)

	const renderContainer = (
		children: React.ReactNode,
		{ dismiss }: { dismiss: () => void }
	) => (
		<View style={styles.galleryContainer}>
			{children}
			{showUI && (
				<View style={[styles.galleryHeader, { paddingTop: insets.top + 16 }]}>
					<TouchableOpacity
						onPress={handleDownload}
						style={styles.headerButton}
					>
						<Download size={24} color={colors[theme].white} />
					</TouchableOpacity>
					<Text style={styles.galleryTitle}>
						{filteredAssets[selectedImageIndex]?.userDefinedName ||
							DEFAULT_IMAGE_NAME}
					</Text>
					<TouchableOpacity onPress={dismiss} style={styles.headerButton}>
						<X size={24} color={colors[theme].white} />
					</TouchableOpacity>
				</View>
			)}
		</View>
	)

	return (
		<View
			style={[
				styles.container(theme),
				{
					paddingTop: insets.top
				}
			]}
		>
			<SearchBarOverlay
				isSearchBarOpen={isSearchBarOpen}
				setIsSearchBarOpen={setIsSearchBarOpen}
				searchInputRef={searchInputRef}
				searchValue={searchValue}
				setSearchValue={setSearchValue}
				placeholder={SEARCH_PLACEHOLDER}
				storageKey="asset-search-history"
			/>

			<HeaderBar title="Assets" onClose={onClose} showBackButton />

			<View style={styles.searchBarContainer}>
				<SearchBarContainer
					searchInputRef={searchInputRef}
					setIsSearchBarOpen={setIsSearchBarOpen}
					searchValue={searchValue}
					setSearchValue={setSearchValue}
					placeholder={SEARCH_PLACEHOLDER}
				/>
			</View>

			<View style={styles.contentContainer}>
				<AnimatedFlatList
					itemLayoutAnimation={LinearTransition}
					contentContainerStyle={[
						styles.flatListContent,
						{ flexGrow: filteredAssets.length > 0 ? 0 : 1 }
					]}
					columnWrapperStyle={styles.columnWrapper}
					numColumns={COLUMN_COUNT}
					contentInset={{
						bottom: LIST_BOTTOM_INSET
					}}
					scrollIndicatorInsets={{
						bottom: LIST_BOTTOM_INSET
					}}
					ListEmptyComponent={renderListEmptyComponent}
					data={filteredAssets}
					renderItem={renderAssetItem}
					keyExtractor={(item) => item.id}
				/>
			</View>

			<LinearGradient
				colors={[colors[theme].background + '00', colors[theme].background]}
				style={styles.gradient}
				pointerEvents="none"
			/>

			<View
				style={[styles.buttonContainer, { paddingBottom: insets.bottom + 16 }]}
			>
				<Button
					text={isUploadingAsset ? 'Uploading...' : 'Upload image'}
					onPress={handleUploadImage}
					disabled={isUploadingAsset}
				/>
			</View>

			<Modal
				visible={isGalleryOpen}
				transparent
				animationType="none"
				onRequestClose={handleDismiss}
				statusBarTranslucent
			>
				<GestureViewer
					id="assets"
					data={filteredAssets.map((asset) => asset.url)}
					initialIndex={selectedImageIndex}
					renderItem={renderImage}
					onDismiss={handleDismiss}
					onDismissStart={handleDismissStart}
					onIndexChange={handleIndexChange}
					ListComponent={FlatList}
					triggerAnimation={triggerAnimationConfig}
					renderContainer={renderContainer}
				/>
			</Modal>

			<DeleteAssetBottomSheet
				bottomInset={insets.bottom}
				onDelete={handleDeleteAsset}
				bottomSheetRef={deleteBottomSheetRef}
			/>
		</View>
	)
}

const styles = defineStyles({
	container: (theme: Theme) => ({
		flex: 1,
		backgroundColor: colors[theme].background,
		paddingHorizontal: 24
	}),
	searchBarContainer: {
		paddingVertical: 20
	},
	contentContainer: {
		flex: 1
	},
	flatListContent: {
		gap: ITEM_SPACING
	},
	columnWrapper: {
		gap: ITEM_SPACING
	},
	emptyStateWrapper: {
		flex: 1,
		marginBottom: '40%'
	},
	thumbnailWrapper: {
		flex: 1,
		aspectRatio: 1,
		borderRadius: 4,
		overflow: 'hidden',
		maxWidth: `${100 / COLUMN_COUNT}%`
	},
	thumbnail: {
		width: '100%',
		height: '100%'
	},
	thumbnailImage: {
		width: '100%',
		height: '100%'
	},
	buttonContainer: {
		position: 'absolute',
		bottom: 0,
		width: '100%',
		alignSelf: 'center'
	},
	gradient: {
		position: 'absolute',
		bottom: 0,
		left: 0,
		right: 0,
		height: 250
	},
	fullSize: {
		width: '100%',
		height: '100%'
	},
	galleryContainer: {
		flex: 1
	},
	galleryHeader: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'space-between',
		paddingHorizontal: 24,
		paddingBottom: 16
	},
	galleryTitle: {
		color: 'white',
		fontSize: 17,
		fontWeight: '600',
		flex: 1,
		textAlign: 'center'
	},
	headerButton: {
		width: 44,
		height: 44,
		alignItems: 'center',
		justifyContent: 'center'
	}
})
